from pathlib import Path
import os
home = Path('/home/aluno')
problems = []
path = home / 'plano.txt'
if not path.is_file():
    problems.append('plano.txt deve existir como arquivo.')
elif path.read_bytes() != b'Planejamento da equipe.\nEntrega: sexta-feira.\n':
    problems.append('plano.txt não contém o conteúdo completo esperado. Preserve texto, ordem e repetições, sem acrescentar numeração ou títulos.')
if os.path.lexists(home / 'rascunho.txt'):
    problems.append('rascunho.txt não deve permanecer no diretório inicial.')
import shlex

# Tokenize command invocations, not mentions in comments or string arguments.
source = Path(os.environ['SHELLBLOCKS_USER_SCRIPT_FILE']).read_text()
lexer = shlex.shlex(source, posix=True, punctuation_chars=';&|()<>\n')
lexer.whitespace = ' \t\r'
lexer.whitespace_split = True
commands = []
command = []
try:
    for token in lexer:
        if token and all(character in ';&|()<>\n' for character in token):
            if command:
                commands.append(command)
                command = []
        else:
            command.append(token)
except ValueError:
    problems.append('Neste tutorial, use mv para mover rascunho.txt para plano.txt, preservando seu conteúdo.')
if command:
    commands.append(command)

cwd = home
used_tool = False
for command in commands:
    executable, *arguments = command
    if executable == 'cd' and len(arguments) == 1:
        cwd = Path(os.path.abspath(cwd / arguments[0]))
        continue
    if executable not in ('mv', '/bin/mv', '/usr/bin/mv'):
        continue
    arguments = [argument for argument in arguments if not argument.startswith('-')]
    paths = [Path(os.path.abspath(cwd / argument)) for argument in arguments]
    if len(arguments) == 2 and paths == [home / 'rascunho.txt', home / 'plano.txt']:
        used_tool = True
if not used_tool:
    problems.append('Neste tutorial, use mv para mover rascunho.txt para plano.txt, preservando seu conteúdo.')

if problems:
    print('\n'.join(problems))
    raise SystemExit(1)
print('OK')
